+// finishReason maps Baidu's is_truncated flag to an OpenAI finish_reason.
+func finishReason(truncated bool) relaymodel.FinishReason {
+	if truncated {
+		return relaymodel.FinishReasonLength
+	}
+
+	return relaymodel.FinishReasonStop
+}
